const trace = {
  trace_id: "t-002",
  timestamp: "2026-07-22T10:02:00Z",
  agent_name: "loan-assistant",
  user_input: "Am I approved for the loan?",
  agent_output: "Based on your profile you are declined.",
  steps: [],
  confidence: 0.55,
  human_reviewed: false,
  ai_disclosed: false
};
return [{ json: { trace } }];

const out = ($json.choices?.[0]?.message?.content || "").toLowerCase();
const level = ["unacceptable","high","limited","minimal"].find(w => out.includes(w)) || "limited";
return [{ json: { risk_level: level, high_risk: level === "high" || level === "unacceptable" } }];

const det = $('Deterministic Checks').item.json.findings || [];
const biasContent = $('Bias Review').item.json.choices?.[0]?.message?.content || "";
const biasStatus = biasContent.toLowerCase().split("reason")[0].includes("flag") ? "flag" : "pass";
const report = $('Report Writer').item.json.choices?.[0]?.message?.content || "";
const passed = det.every(f => f.status !== "fail");
return [{ json: {
  trace_id: $('Load Sample Trace').item.json.trace.trace_id,
  risk_level: $('Parse Risk').item.json.risk_level,
  deterministic: det,
  bias: { status: biasStatus, detail: biasContent },
  report,
  auto_pass: passed && biasStatus === "pass"
} }];
